    // add `available` to the URL query string
    if (getAvailable() != null) {
      joiner.add(String.format(java.util.Locale.ROOT, "%savailable%s=%s", prefix, suffix, ApiClient.urlEncode(ApiClient.valueToString(getAvailable()))));
    }

    // add `unavailable_reason` to the URL query string
    if (getUnavailableReason() != null) {
      joiner.add(String.format(java.util.Locale.ROOT, "%sunavailable_reason%s=%s", prefix, suffix, ApiClient.urlEncode(ApiClient.valueToString(getUnavailableReason()))));
    }

    // add `connect_url` to the URL query string
    if (getConnectUrl() != null) {
      joiner.add(String.format(java.util.Locale.ROOT, "%sconnect_url%s=%s", prefix, suffix, ApiClient.urlEncode(ApiClient.valueToString(getConnectUrl()))));
    }

    // add `invoke` to the URL query string
    if (getInvoke() != null) {
      joiner.add(getInvoke().toUrlQueryString(prefix + "invoke" + suffix));
    }

    // add `input_schema` to the URL query string
    if (getInputSchema() != null) {
      joiner.add(String.format(java.util.Locale.ROOT, "%sinput_schema%s=%s", prefix, suffix, ApiClient.urlEncode(ApiClient.valueToString(getInputSchema()))));
    }

    return joiner.toString();
